import{_ as t,o,c as i,ao as a}from"./chunks/framework.D7TN4pt9.js";const u=JSON.parse('{"title":"Ship of Tools — Phase 1 plan (historical)","description":"","frontmatter":{},"headers":[],"relativePath":"design/roadmap.md","filePath":"design/roadmap.md","lastUpdated":null}'),r={name:"design/roadmap.md"};function s(d,e,n,l,c,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="Ship-of-Tools-—-Phase-1-plan-historical" tabindex="-1">Ship of Tools — Phase 1 plan (historical) <a class="header-anchor" href="#Ship-of-Tools-—-Phase-1-plan-historical" aria-label="Permalink to &quot;Ship of Tools — Phase 1 plan (historical) {#Ship-of-Tools-—-Phase-1-plan-historical}&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Status: partly built</p><p>This is the original phase-1 plan, kept as a record. The table below says which of its parts are built.</p></div><p>The plan names files, plugin packages and a TUI that were not built, and it was written before capsule rows replaced tmux sessions. Read it for the reasoning behind the milestones, not as a description of the code. What is built is described in the rest of this manual; the unbuilt parts are described, marked unbuilt, in <a href="./../guide/modes">Modes</a>, <a href="./../guide/concept-layer">The Concept Layer</a>, <a href="./../guide/color-coding">Color Coding</a>, <a href="./../extend/abi">The Dispatch ABI</a> and <a href="./../extend/mode">Mode plugins</a>. (These links resolve in the built manual, where this file is staged as <code>design/roadmap.md</code>; on GitHub they do not.)</p><table tabindex="0"><thead><tr><th style="text-align:right;">Plan part</th><th style="text-align:right;">Status</th><th style="text-align:right;">What is true now</th></tr></thead><tbody><tr><td style="text-align:right;">M1 native window: winit, wgpu, ratatui cells painted with cosmic-text</td><td style="text-align:right;">Built</td><td style="text-align:right;"><code>WgpuBackend</code> in <code>rust/frontend/src/ui/render/cells.rs</code>; the window is not a terminal program</td></tr><tr><td style="text-align:right;">M1 previews: PNG, markdown, MathJax SVG</td><td style="text-align:right;">Built</td><td style="text-align:right;"><code>rust/frontend/src/ui/preview/image/</code>, <code>rust/frontend/src/ui/preview/markdown/</code>, <code>rust/backend/src/sidecars/mathjax.rs</code></td></tr><tr><td style="text-align:right;">M1 remote backend in a named tmux session, reconnect by revision</td><td style="text-align:right;">Partly built</td><td style="text-align:right;">Reconnect replays by <code>last_seen_revision</code> (<code>rust/backend/src/server/hello.rs</code>); the daemon starts no tmux sessions, rows are capsule rows</td></tr><tr><td style="text-align:right;">M2 Files mode with file watching</td><td style="text-align:right;">Built</td><td style="text-align:right;"><code>rust/backend/src/files/watcher.rs</code> sends <code>preview.changed</code></td></tr><tr><td style="text-align:right;">M3 Modules mode, read-only</td><td style="text-align:right;">Built</td><td style="text-align:right;"><code>project.scan</code> in <code>julia/kernel/src/project_scan.jl</code>, tree in <code>rust/frontend/src/ui/nav/modules.rs</code>; no <code>modules-mode</code> plugin package exists</td></tr><tr><td style="text-align:right;">M4 persistent REPL with line, block and file dispatch</td><td style="text-align:right;">Partly built</td><td style="text-align:right;">REPL in <code>rust/backend/src/sidecars/repl/</code> and <code>julia/repl/</code>; per-line and per-block dispatch is not built</td></tr><tr><td style="text-align:right;">M5 <code>.concept/</code> annotations with AST-hash provenance</td><td style="text-align:right;">Partly built</td><td style="text-align:right;"><code>concept.read</code>, <code>concept.write</code> and <code>concept.list</code> exist; staleness compares a file hash, per-entity <code>ast_hash</code> is unused, one-key refresh is not built</td></tr><tr><td style="text-align:right;">M6 orchestrator chat with tools</td><td style="text-align:right;">Not built</td><td style="text-align:right;">no orchestrator code in <code>rust/backend/src/</code>; <code>requirements.md</code> marks it NOT BUILT</td></tr><tr><td style="text-align:right;">M7 HDF5Preview as an external plugin</td><td style="text-align:right;">Partly built</td><td style="text-align:right;"><code>examples/plugins/HDF5Preview/</code> loads through <code>LAZY_PLUGIN_FOR_EXT</code>; nothing reads <code>[sot].extensions</code></td></tr><tr><td style="text-align:right;">Types, Math and Outputs modes; the Agents mode</td><td style="text-align:right;">Not built</td><td style="text-align:right;"><a href="./../guide/modes">Modes</a></td></tr></tbody></table><p>A dependency-ordered plan. The first milestone is a thin end-to-end skeleton; each subsequent milestone adds exactly one capability.</p><blockquote><p><strong>Note (2026-05-07):</strong> Plan revised after the C-pivot. The original plan assumed the frontend was a TUI rendered into the user&#39;s terminal. That premise was wrong for the user&#39;s deployment (Windows → SSH → tmux → Linux remote). The revised plan keeps the kernel, core IR, line protocol, and backend daemon intact but rebuilds the frontend as a <strong>native local window</strong> that owns rendering end-to-end.</p></blockquote><h2 id="Scope" tabindex="-1">Scope <a class="header-anchor" href="#Scope" aria-label="Permalink to &quot;Scope {#Scope}&quot;">​</a></h2><p>The plan&#39;s scope:</p><ul><li><p>Files mode (filesystem nav with previews — markdown, PNG, syntax-highlighted .jl)</p></li><li><p>Modules mode, read-only (structural via <code>JuliaSyntax.jl</code>)</p></li><li><p>Persistent Julia REPL with code dispatch (line, block, file)</p></li><li><p>Orchestrator LLM chat with file + REPL tools</p></li><li><p><code>.concept/</code> annotation read+write with AST-hash provenance</p></li><li><p>One demo external plugin (HDF5 preview), validating the ABI from outside core</p></li></ul><p>Out: Types/Math/Outputs modes, multi-agent, multi-laptop semantics beyond first-wins, background staleness sweep, embedded editor, MP4 playback, automatic plot capture.</p><h2 id="Risk-register" tabindex="-1">Risk register <a class="header-anchor" href="#Risk-register" aria-label="Permalink to &quot;Risk register {#Risk-register}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Risk</th><th style="text-align:right;">De-risked in</th></tr></thead><tbody><tr><td style="text-align:right;">Native rendering of markdown + PNG + MathJax-SVG end-to-end</td><td style="text-align:right;"><strong>M1 spike</strong> (the go/no-go gate)</td></tr><tr><td style="text-align:right;">ratatui custom backend (cell stream into wgpu) — prior art partial</td><td style="text-align:right;">M1 spike: try <code>ratatui-wgpu</code> first; roll our own if it can&#39;t carry our requirements</td></tr><tr><td style="text-align:right;">SSH Unix-socket forwarding on Windows OpenSSH</td><td style="text-align:right;">M1 spike: confirm StreamLocalBindUnlink + LocalForward path; TCP per-session port is the fallback</td></tr><tr><td style="text-align:right;">Reconnect restoring state without losing in-flight work</td><td style="text-align:right;">M1 spike: kill the frontend, restart, see kernel state and tree position resume</td></tr><tr><td style="text-align:right;">Cross-platform Julia subprocess supervision</td><td style="text-align:right;">M2 — verify no orphaned <code>julia</code> after Ctrl-C / <code>taskkill</code> / task-manager kill</td></tr><tr><td style="text-align:right;">AST hash stability across <code>JuliaSyntax</code> versions</td><td style="text-align:right;">M3 property test + pinned version + pinned hash format</td></tr><tr><td style="text-align:right;"><code>JuliaSyntax</code> parsing perf on large files</td><td style="text-align:right;">M3 cache by <code>(path, mtime, size)</code></td></tr><tr><td style="text-align:right;">Anthropic streaming + tool-use loop</td><td style="text-align:right;">M6 — build against recorded fixture before live API</td></tr></tbody></table><h2 id="Milestones" tabindex="-1">Milestones <a class="header-anchor" href="#Milestones" aria-label="Permalink to &quot;Milestones {#Milestones}&quot;">​</a></h2><h3 id="M0-—-Decisions-and-scaffolding-DONE-—-pivoted" tabindex="-1">M0 — Decisions and scaffolding (DONE — pivoted) <a class="header-anchor" href="#M0-—-Decisions-and-scaffolding-DONE-—-pivoted" aria-label="Permalink to &quot;M0 — Decisions and scaffolding (DONE — pivoted) {#M0-—-Decisions-and-scaffolding-DONE-—-pivoted}&quot;">​</a></h3><p><strong>Status:</strong> core/, julia/kernel/, rust/protocol/, rust/backend/ scaffolds are committed and stay. rust/frontend/ as committed targeted crossterm; pruned in the M0 closeout (the <code>ratatui-image</code> / <code>crossterm</code> deps and <code>rust/scratch/img-probe/</code> are removed).</p><h3 id="M1-—-Spike:-native-window-chrome-previews-remote-socket-reconnect-1-week" tabindex="-1">M1 — Spike: native window + chrome + previews + remote socket + reconnect (1 week) <a class="header-anchor" href="#M1-—-Spike:-native-window-chrome-previews-remote-socket-reconnect-1-week" aria-label="Permalink to &quot;M1 — Spike: native window + chrome + previews + remote socket + reconnect (1 week) {#M1-—-Spike:-native-window-chrome-previews-remote-socket-reconnect-1-week}&quot;">​</a></h3><p>The go/no-go gate for option C. If this lands, C is defensible. If preview-layer requirements start pulling in HTML/iframes/WebGL within the spike, fall back to <strong>option B</strong> (Tauri webview wrapping a web frontend) — kernel/backend/protocol stay intact across the swap.</p><p><strong>Deliverable:</strong> a single <code>sot</code> binary that:</p><ol><li><p>Opens a native local window (winit + wgpu).</p></li><li><p>Runs a ratatui chrome layer (the mode tree, status bar, focus) via a custom <code>Backend</code> impl that paints cells with cosmic-text into the wgpu surface.</p></li><li><p>Renders a preview pane in three modes:</p><ul><li><p>PNG via <code>image</code> → wgpu texture</p></li><li><p>Markdown via comrak → cosmic-text laid out lines</p></li><li><p>Inline math via MathJax-served SVG → resvg → wgpu texture</p></li></ul></li><li><p>Connects to a backend instance running in a named tmux session on a remote host via SSH-forwarded per-session Unix socket; reconnects after frontend kill restoring tree position and last preview.</p></li></ol><p><strong>Files (sketch):</strong></p><ul><li><p><code>rust/frontend/src/main.rs</code> — winit event loop, wgpu surface init, connect-and-spawn flow.</p></li><li><p><code>rust/frontend/src/ui/render/cells.rs</code> — ratatui custom <code>Backend</code> impl.</p></li><li><p><code>rust/frontend/src/ui/preview/mod.rs</code> — preview-layer dispatch on MIME.</p></li><li><p><code>rust/frontend/src/ui/preview/{image/png,markdown/mod,image/svg}.rs</code> — three concrete renderers.</p></li><li><p><code>rust/frontend/src/net/transport/mod.rs</code> — SSH-spawn + Unix-socket connect + reconnect loop.</p></li><li><p><code>rust/backend/src/main.rs</code> — Unix-socket listener, session-id handshake, kernel supervisor.</p></li><li><p><code>rust/backend/src/session.rs</code> — session state (tree cursor, preview cache, revision counter for reconnect).</p></li><li><p><code>rust/backend/src/sidecars/mathjax.rs</code> — Node sidecar wrapper (math snippet → SVG).</p></li><li><p><code>julia/kernel/src/ShipToolsKernel.jl</code> — minimal NDJSON dispatch returning fixed payloads for the spike.</p></li><li><p><code>rust/protocol/src/lib.rs</code> — Request/Response/Event enums for the spike&#39;s ops only (<code>hello</code>, <code>preview.get</code>, <code>tree.root</code>).</p></li></ul><p><strong>Acceptance:</strong></p><ul><li><p>Render PNG side-by-side with a real CairoMakie figure, eyeball quality.</p></li><li><p>Render a markdown file with embedded LaTeX (<code>$\\int_0^\\infty e^{-x^2}\\,dx$</code>); math appears typeset, not as a code box.</p></li><li><p>Kill the frontend with the backend running; relaunch; tree cursor and preview restore from <code>last_seen_revision</code>.</p></li><li><p>Run on Linux (local → local-loopback) and Windows (Windows local → Linux remote) end to end.</p></li></ul><p>If any of those fail in a way the architecture can&#39;t fix, switch to option B before continuing.</p><h3 id="M2-—-Files-mode-populated,-file-watching-3–4-days" tabindex="-1">M2 — Files mode populated, file watching (3–4 days) <a class="header-anchor" href="#M2-—-Files-mode-populated,-file-watching-3–4-days" aria-label="Permalink to &quot;M2 — Files mode populated, file watching (3–4 days) {#M2-—-Files-mode-populated,-file-watching-3–4-days}&quot;">​</a></h3><p><strong>Deliverable:</strong> real filesystem navigation. <code>.md</code> rendered, <code>.png</code> rendered, <code>.jl</code> shown as syntax-highlighted text. External edits update the tree within 500 ms.</p><p><strong>Files:</strong></p><ul><li><p><code>julia/plugins/files-mode/src/FilesMode.jl</code> — <code>tree_root</code>, <code>tree_children</code>, <code>preview_for</code>.</p></li><li><p><code>julia/plugins/markdown/src/MarkdownPreview.jl</code> — <code>preview(::Type{MarkdownDoc}, path) → PreviewPayload(mime=&quot;text/markdown&quot;, data=bytes)</code>.</p></li><li><p><code>julia/plugins/png/src/PngPreview.jl</code> — read bytes → <code>image/png</code> payload.</p></li><li><p><code>julia/plugins/julia-source/src/JuliaSourcePreview.jl</code> — read + syntect-friendly metadata → <code>text/plain</code> with extras.</p></li><li><p><code>rust/backend/src/files/watcher.rs</code> — <code>notify</code> watcher → <code>file.changed</code> events.</p></li></ul><p><strong>Acceptance:</strong> open the Ship of Tools repo, navigate to <code>requirements.md</code>, see it rendered. Drop a PNG, navigate, see it. Edit a file externally; tree refreshes.</p><h3 id="M3-—-Modules-mode-read-only-AST-hash-3–4-days" tabindex="-1">M3 — Modules mode (read-only) + AST hash (3–4 days) <a class="header-anchor" href="#M3-—-Modules-mode-read-only-AST-hash-3–4-days" aria-label="Permalink to &quot;M3 — Modules mode (read-only) + AST hash (3–4 days) {#M3-—-Modules-mode-read-only-AST-hash-3–4-days}&quot;">​</a></h3><p><strong>Deliverable:</strong> hotkey switches root tree from Files to Modules. Columns: modules → functions → methods. Preview shows method source.</p><p><strong>Files:</strong></p><ul><li><p><code>julia/plugins/julia-source/src/JuliaSourceParser.jl</code> — <code>parse_entities</code> walks <code>JuliaSyntax.parseall</code>.</p></li><li><p><code>julia/plugins/julia-source/src/Index.jl</code> — project index keyed by <code>(path, mtime, size)</code>; incremental rebuild on <code>file.changed</code>.</p></li><li><p><code>julia/plugins/modules-mode/src/ModulesMode.jl</code> — mode-tree dispatch.</p></li><li><p><code>core/src/ASTHash.jl</code> — hash function.</p></li><li><p><code>core/test/test_ast_hash.jl</code> — property test.</p></li><li><p><code>rust/frontend/src/ui/nav/tree_store.rs</code> — per-mode cursor preservation; modes switch via <code>f</code> / <code>m</code> / <code>s</code> / <code>h</code> in nav focus.</p></li></ul><p><strong>Acceptance:</strong> open the Ship of Tools repo, switch to Modules mode, navigate to a method, see source. Property test passes.</p><h3 id="M4-—-Persistent-REPL-with-code-dispatch-3–4-days" tabindex="-1">M4 — Persistent REPL with code dispatch (3–4 days) <a class="header-anchor" href="#M4-—-Persistent-REPL-with-code-dispatch-3–4-days" aria-label="Permalink to &quot;M4 — Persistent REPL with code dispatch (3–4 days) {#M4-—-Persistent-REPL-with-code-dispatch-3–4-days}&quot;">​</a></h3><p><strong>Deliverable:</strong> toggleable REPL pane (<code>~</code>). <code>&lt;Enter&gt;</code> evaluates the line at cursor; <code>&lt;S-Enter&gt;</code> evaluates the surrounding top-level block; <code>&lt;C-Enter&gt;</code> includes the whole file. CairoMakie figures render inline through the preview-layer (NOT through any terminal protocol).</p><blockquote><p>Shipped (diverged from the original plan): the REPL toggles with <code>Ctrl+J</code>; whole-file run landed as Files-mode <code>r</code> (fresh REPL) / <code>R</code> (current session); at the prompt <code>Enter</code> submits and <code>Shift+Enter</code> inserts a newline. Per-line / per-block dispatch is still planned.</p></blockquote><p><strong>Files:</strong></p><ul><li><p><code>repl/Project.toml</code>, <code>repl/src/ShipToolsRepl.jl</code>.</p></li><li><p><code>repl/src/DisplayShim.jl</code> — <code>MIMEDisplay</code> emits framed JSON.</p></li><li><p><code>rust/backend/src/sidecars/repl/</code> — REPL supervisor; <code>repl.eval</code> streams <code>repl.frame</code> events tagged with <code>eval_id</code>.</p></li><li><p><code>rust/frontend/src/repl_pane.rs</code> — consumes <code>repl.frame</code>, dispatches to preview-layer for inline images.</p></li><li><p><code>rust/frontend/src/dispatch.rs</code> — block-span computation via kernel round-trip.</p></li></ul><p><strong>Acceptance:</strong> <code>x = 1+1</code> → <code>2</code>. Plot returns a wgpu texture inline. Killing REPL via UI doesn&#39;t kill kernel; restart works.</p><h3 id="M5-—-.concept/-annotations-with-AST-hash-provenance-2–3-days" tabindex="-1">M5 — <code>.concept/</code> annotations with AST-hash provenance (2–3 days) <a class="header-anchor" href="#M5-—-.concept/-annotations-with-AST-hash-provenance-2–3-days" aria-label="Permalink to &quot;M5 — `.concept/` annotations with AST-hash provenance (2–3 days) {#M5-—-.concept/-annotations-with-AST-hash-provenance-2–3-days}&quot;">​</a></h3><p><strong>Deliverable:</strong> Modules-mode preview shows source on top, matching <code>.concept/</code> annotation below. Stale badge when AST hash mismatches. <code>&lt;S-e&gt;</code> opens annotation in <code>$EDITOR</code>. <code>&lt;r&gt;</code> refreshes provenance. <em>(As built: the annotation is edited inline with <code>e</code> / <code>Ctrl+S</code> rather than via <code>$EDITOR</code>, and the one-key <code>&lt;r&gt;</code> provenance refresh was not implemented — see the <a href="./../guide/concept-layer">concept layer</a> guide.)</em></p><p><strong>Files:</strong></p><ul><li><p><code>julia/plugins/concept/src/ConceptStore.jl</code> — <code>read_annotation</code>, <code>write_annotation</code>, <code>is_stale</code>. YAML frontmatter via <code>YAML.jl</code>.</p></li><li><p><code>julia/plugins/concept/src/Provenance.jl</code> — stamps <code>synced_against</code> and <code>synced_at</code> on write.</p></li><li><p><code>julia/plugins/modules-mode/src/ModulesMode.jl</code> — extend <code>preview_for</code> to compose source + annotation + badge.</p></li><li><p><code>rust/frontend/src/preview/composite.rs</code> — multi-pane preview composition (source on top, annotation below, badge overlay).</p></li><li><p><code>rust/backend/src/editor.rs</code> — shell out to <code>$EDITOR</code>, await exit, signal kernel re-read.</p></li></ul><p><strong>Acceptance:</strong> create a method, write annotation, save. Modify the body; reopen → annotation shows stale badge. <code>&lt;r&gt;</code> clears it. <em>(As built, the badge is cleared by re-editing and re-saving the annotation, not by a dedicated <code>&lt;r&gt;</code> keypress.)</em></p><h3 id="M6-—-Orchestrator-chat-with-tool-dispatch-4–5-days" tabindex="-1">M6 — Orchestrator chat with tool dispatch (4–5 days) <a class="header-anchor" href="#M6-—-Orchestrator-chat-with-tool-dispatch-4–5-days" aria-label="Permalink to &quot;M6 — Orchestrator chat with tool dispatch (4–5 days) {#M6-—-Orchestrator-chat-with-tool-dispatch-4–5-days}&quot;">​</a></h3><p><strong>Deliverable:</strong> chat pane (<code>&lt;Space&gt;c</code>). User types; orchestrator streams. Tools: <code>read_file</code>, <code>write_file</code>, <code>read_annotation</code>, <code>write_annotation</code>, <code>repl_eval</code>, <code>list_modules</code>. Demo: &quot;summarize module X&quot; → tool calls visible as collapsed breadcrumbs → optional annotation written.</p><p><strong>Files:</strong></p><ul><li><p><code>rust/backend/src/orchestrator/mod.rs</code> — Anthropic client, SSE streaming, tool-use loop.</p></li><li><p><code>rust/backend/src/orchestrator/tools.rs</code> — tool spec construction.</p></li><li><p><code>rust/backend/src/orchestrator/cache.rs</code> — four-block cache scheme.</p></li><li><p><code>rust/frontend/src/chat_pane.rs</code> — input area, transcript, streaming render via cosmic-text, collapsed tool-call breadcrumbs.</p></li><li><p><code>core/src/ToolSpec.jl</code> — <code>tool_spec</code> and <code>tool_call</code> dispatch surfaces <em>defined but unwired</em>. Phase 2 seam.</p></li></ul><p><strong>Acceptance:</strong> ask the orchestrator to &quot;create an annotation for function X.&quot; File appears with proper frontmatter; reopening Modules mode shows the new annotation.</p><h3 id="M7-—-Demo-external-plugin:-HDF5Preview.jl-1–2-days" tabindex="-1">M7 — Demo external plugin: <code>HDF5Preview.jl</code> (1–2 days) <a class="header-anchor" href="#M7-—-Demo-external-plugin:-HDF5Preview.jl-1–2-days" aria-label="Permalink to &quot;M7 — Demo external plugin: `HDF5Preview.jl` (1–2 days) {#M7-—-Demo-external-plugin:-HDF5Preview.jl-1–2-days}&quot;">​</a></h3><p><strong>Deliverable:</strong> separate package at <code>examples/plugins/HDF5Preview/</code> that, when listed in a project&#39;s <code>[sot].extensions</code>, makes <code>.h5</code> files previewable.</p><p><strong>Files:</strong></p><ul><li><p><code>examples/plugins/HDF5Preview/Project.toml</code> — depends on <code>ConceptExplorerCore</code>, <code>HDF5</code>.</p></li><li><p><code>examples/plugins/HDF5Preview/src/HDF5Preview.jl</code> — <code>struct H5File &lt;: FileType end</code>, dispatches <code>preview</code>.</p></li><li><p><code>examples/plugins/README.md</code>.</p></li></ul><p><strong>Acceptance:</strong> drop an <code>.h5</code>, add <code>HDF5Preview</code> to <code>[sot].extensions</code>, navigate, see structured preview. <strong>Zero Rust changes were required.</strong> That&#39;s the test of the ABI. (As built: the kernel loads HDF5Preview through <code>LAZY_PLUGIN_FOR_EXT</code>, and the daemon&#39;s <code>is_bounded_output_plugin</code> names <code>.h5</code>, <code>.hdf5</code> and <code>.hdf</code>, which is a Rust change.)</p>',55)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
